// RPC helper — child worker reachable via service binding (both fetch and RPC).
export class RpcEntrypoint {
  async ping() { return 'pong-from-rpc-helper'; }
  async getMetric(key) { return { key, value: Math.random() }; }
}
export default {
  async fetch(request) {
    return Response.json({ from: 'svcchain-rpc-helper', path: new URL(request.url).pathname });
  },
};

// Parent worker — exercises service binding (fetch + RPC), DO, KV, and request.cf.tls* exposure.

export class SessionDO {
  constructor(state) { this.state = state; }
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === '/incr') {
      const c = (await this.state.storage.get('count') || 0) + 1;
      await this.state.storage.put('count', c);
      return Response.json({ count: c });
    }
    if (url.pathname === '/list') {
      const all = await this.state.storage.list();
      return Response.json([...all]);
    }
    return Response.json({ do: 'SessionDO' });
  }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === '/tls-info') {
      // O2O quirk: request.cf.tls* may be empty on SaaS-side workers.
      return Response.json({
        tlsVersion: request.cf?.tlsVersion ?? null,
        tlsCipher: request.cf?.tlsCipher ?? null,
        tlsClientAuth: request.cf?.tlsClientAuth ?? null,
      });
    }
    if (url.pathname === '/rpc-fetch') {
      const r = await env.RPC_HELPER.fetch(new URL('/health', request.url));
      return new Response(await r.text(), { headers: { 'X-Via': 'service-fetch' } });
    }
    if (url.pathname === '/rpc-call') {
      const result = await env.RPC_HELPER_RPC.ping();
      return Response.json({ result, via: 'rpc' });
    }
    if (url.pathname.startsWith('/do/')) {
      const id = env.SESSION.idFromName('default');
      const stub = env.SESSION.get(id);
      return stub.fetch(request);
    }
    if (url.pathname === '/config') {
      const v = await env.CONFIG.get('config:version');
      return Response.json({ version: v });
    }
    if (url.pathname === '/cache') {
      const v = await env.CACHE.get('cache:warm:home');
      return new Response(v ?? '');
    }
    return Response.json({ from: 'svcchain-parent', help: ['/rpc-fetch', '/rpc-call', '/do/incr', '/do/list', '/config', '/cache', '/tls-info'] });
  }
};
